// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout, MatrixTriangle } from '@stdlib/types/blas';

/**
* Interface describing `dpbtf2`.
*/
interface Routine {
	/**
	* Computes an unblocked Cholesky factorization of a real symmetric positive definite band matrix in place.
	*
	* ## Notes
	*
	* -   The full compact view is H-by-N, H=KD+1; KD may exceed N-1.
	* -   Only the selected original triangle is used; unused band cells, padding and guards preserve their bits.
	* -   INFO=0 reports completion. Positive INFO is the first one-based diagonal where the source comparison finds a value <=0; the failed diagonal is not assigned at that step.
	* -   Earlier factor/trailing updates remain and later steps do not run; no rollback is performed.
	* -   No finite-input or NaN precheck is added; INFO=0 does not certify finite factors or numerical stability.
	* -   Active AB must be an intrinsic Float64Array backed by an ordinary ArrayBuffer; valid current resizable extents are supported and SharedArrayBuffer is rejected.
	* -   Backing must remain stable and exclusive throughout the synchronous call; hidden foreign physical aliases are outside the caller contract.
	* -   The entire active band view must fit and be injective; used zero strides and unsafe exact-index arithmetic are rejected before writes.
	* -   For N=0, scalar validation completes before returning zero without array access, dispatch or writes; main LDAB still meets its layout-specific bound.
	* -   Type annotations do not encode runtime geometry, backing, lifetime, configured native-width or helper bounds.
	*
	* @param order - row-major (101) or column-major (102) compact-band layout
	* @param uplo - upper (121) or lower (122) stored triangle
	* @param N - nonnegative safe matrix order, at most 2147483647
	* @param KD - nonnegative safe bandwidth, at most 2147483647
	* @param AB - full input/output (KD+1)-by-N compact band view
	* @param LDAB - leading dimension; at least KD+1 column-major or max(1,N) row-major
	* @throws selectors, active intrinsic array type and backing must be valid
	* @throws dimensions, geometry, bounds and exact arithmetic must meet the runtime domain
	* @returns numeric INFO, zero or the first one-based failed diagonal
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var AB = new Float64Array( [ 4.0, 10.0, 17.0, 2.0, 3.0, 999.0 ] );
	* var info = dpbtf2( 'row-major', 'lower', 3, 1, AB, 3 );
	* // returns 0
	* // AB => <Float64Array>[ 2.0, 3.0, 4.0, 1.0, 1.0, 999.0 ]
	*/
	( order: Layout | 101 | 102, uplo: MatrixTriangle | 121 | 122, N: number, KD: number, AB: Float64Array, LDAB: number ): number;

	/**
	* Computes a band Cholesky factorization with alternative indexing semantics.
	*
	* ## Notes
	*
	* -   The full compact view is H-by-N, H=KD+1; KD may exceed N-1.
	* -   Only the selected original triangle is used; unused band cells, padding and guards preserve their bits.
	* -   INFO=0 reports completion. Positive INFO is the first one-based diagonal where the source comparison finds a value <=0; the failed diagonal is not assigned at that step.
	* -   Earlier factor/trailing updates remain and later steps do not run; no rollback is performed.
	* -   No finite-input or NaN precheck is added; INFO=0 does not certify finite factors or numerical stability.
	* -   Active AB must be an intrinsic Float64Array backed by an ordinary ArrayBuffer; valid current resizable extents are supported and SharedArrayBuffer is rejected.
	* -   Backing must remain stable and exclusive throughout the synchronous call; hidden foreign physical aliases are outside the caller contract.
	* -   The entire active band view must fit and be injective; used zero strides and unsafe exact-index arithmetic are rejected before writes.
	* -   For N=0, scalar validation completes before returning zero without array access, dispatch or writes; main LDAB still meets its layout-specific bound.
	* -   Type annotations do not encode runtime geometry, backing, lifetime, configured native-width or helper bounds.
	* -   Strides and offset are element indices relative to the actual typed-array view; independent signed strides are supported.
	* -   Empty calls do not read unused strides or offset. Unused singleton strides normalize only after original full-view validation.
	*
	* @param uplo - upper (121) or lower (122) stored triangle
	* @param N - nonnegative safe matrix order, at most 2147483647
	* @param KD - nonnegative safe bandwidth, at most 2147483647
	* @param AB - full input/output (KD+1)-by-N compact band view
	* @param strideAB1 - band-row element stride
	* @param strideAB2 - matrix-column element stride
	* @param offsetAB - starting band index
	* @throws selectors, active intrinsic array type and backing must be valid
	* @throws dimensions, geometry, bounds and exact arithmetic must meet the runtime domain
	* @returns numeric INFO, zero or the first one-based failed diagonal
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var AB = new Float64Array( [ 7.0, 16.0, 0.0, 4.0, 7.0 ] );
	* var info = dpbtf2.ndarray( 'lower', 3, 0, AB, 1, -1, 3 );
	* // returns 2
	* // AB => <Float64Array>[ 7.0, 16.0, 0.0, 2.0, 7.0 ]
	*/
	ndarray( uplo: MatrixTriangle | 121 | 122, N: number, KD: number, AB: Float64Array, strideAB1: number, strideAB2: number, offsetAB: number ): number;
}

/**
* Computes an unblocked Cholesky factorization of a real symmetric positive definite band matrix.
*
* @param order - row-major (101) or column-major (102) compact-band layout
* @param uplo - upper (121) or lower (122) stored triangle
* @param N - nonnegative safe matrix order, at most 2147483647
* @param KD - nonnegative safe bandwidth, at most 2147483647
* @param AB - full input/output compact band view
* @param LDAB - leading dimension; at least KD+1 column-major or max(1,N) row-major
* @returns numeric INFO, zero or the first one-based failed diagonal
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var AB = new Float64Array( [ 4.0, 10.0, 17.0, 2.0, 3.0, 999.0 ] );
* var info = dpbtf2( 'row-major', 'lower', 3, 1, AB, 3 );
* // returns 0
* // AB => <Float64Array>[ 2.0, 3.0, 4.0, 1.0, 1.0, 999.0 ]
*/
declare var dpbtf2: Routine;


// EXPORTS //

export = dpbtf2;
